sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

          // Add your code here
		var rightNow = new GlideDateTime();

		var overdurNITasks = new GlideRecord('x_58872_needit_needit_task');
		overdurNITasks.addQuery('due_date', '<=', rightNow);
		overdurNITasks.addQuery('state','<',3);
		overdurNITasks.addQuery('assigned_to', current.assigned_to);

		overdurNITasks.query();

		// Verify the number of overdue NeedIt Tasks
		if(overdurNITasks.getRowCount() - 1  <= 0) {
			template.print("");
		} else {
			// Print to the Message field on a notification
			template.print("In addition to this overdue NeedIt Task, you have " + (overdurNITasks.getRowCount() - 1) + " more overdue NeedIt Tasks.");
		}

})(current, template, email, email_action, event);
